import '../App.css';
import LetterGlitch from '../LightPillar';
import React, { useState, useEffect, useRef } from "react";
import { createRoot } from 'react-dom/client';
import { Parallax, ParallaxProvider } from 'react-scroll-parallax';
import { HashRouter as Router, Routes, Route, useNavigate } from 'react-router-dom';
import { cleanup } from '@testing-library/react';

const loadWasm = async () => {
  const wasm = await import("../wasm/closest_pair.js");
  await wasm.default();
  return wasm;
}
let isMounted = false;

export function ClosestPair() {
  let dummy = React.createElement('div', { id: "circle" }, "Circle")
  let dummy2 = React.createElement('div', { id: "circle" }, "Circle2")

  dummy.appendChild(dummy2)
  const rootElement = createRoot(document.getElementById("root"))
  rootElement.render(dummy)

  rootElement.render(dummy2)
  isMounted = false;
  const canvasRef = useRef(null);
  const nav = useNavigate();
  const navigate = () => {
    nav('/closestpair')
  }
  const [points, setPoints] = useState([]);
  const [order, setOrder] = useState([]);
  React.useEffect(() => {
    const getPoint = async () => {
      const closestPair = await loadWasm();
      let canvasStruct = closestPair.instantiateStruct();
      let instance = canvasStruct.initializeCanvas(10, 400, 400);
      await instance;
      if (isMounted == false) {
        setPoints(canvasStruct.returnPointsX());
      }
      isMounted = true;
      return () => {
        cleanup;
      }
    };
    getPoint();
  }, [])
  return (
    <div className="App" ref={canvasRef}>
      <div>

        {points}
      </div>
      <div id="root">

      </div>
      <div>

        {points}
      </div>
    </div>

  );
}
function loaded_element() {
  console.log()
}
